    '''            showDetail(\n                when (mode) {\n                    ArMode.MAP -> "AR ready · preparing shared coordinates…"\n                    ArMode.LIVE -> "AR ready · resolving this place…"\n                    else -> "AR ready · resolving shared location…"\n                }\n            )\n''',
